using ProjetoIntegradorBack.Api.Commands; using ProjetoIntegradorBack.Api.Queries; using ProjetoIntegradorBack.Domain.DTOs; using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using Prime.Architecture.Mapper.Interfaces; using Prime.Architecture.Mediator.Standard.Requests;
namespace ProjetoIntegradorBack.Api.Handlers.NavalhaCorte;
public class ListarFuncionariosHandler(IFuncionarioRepository r,IMapper m):IRequestHandler<ListarFuncionariosQuery,List<FuncionarioDto>>{public async Task<List<FuncionarioDto>> Handle(ListarFuncionariosQuery q,CancellationToken c){var x=await r.ListarPorEstabelecimentoAsync(q.EstabelecimentoId,c);return x.IsSuccess?x.Success!.Select(v=>m.Map<Funcionario,FuncionarioDto>(v)).ToList():[];}}
public class CriarFuncionarioHandler(IFuncionarioRepository r,IMapper m):IRequestHandler<CriarFuncionarioCommand,FuncionarioDto>{public async Task<FuncionarioDto> Handle(CriarFuncionarioCommand q,CancellationToken c){var x=await r.AdicionarAsync(new Funcionario{EstabelecimentoId=q.EstabelecimentoId,UsuarioId=q.UsuarioId,Nome=q.Nome,Email=q.Email,Telefone=q.Telefone,Funcao=q.Funcao,PercentualComissao=q.PercentualComissao,Ativo=true},c);if(x.IsFailure)throw new InvalidOperationException();return m.Map<Funcionario,FuncionarioDto>(x.Success!);}}
